// Report on yesterday (in the workflow's timezone) and prepare the Shopify queries.
const start = $now.minus({ days: 1 }).startOf('day');
const end = $now.startOf('day');
const fmt = "yyyy-MM-dd'T'HH:mm:ssZZ";
return [{
  json: {
    label: start.toFormat('yyyy-MM-dd'),
    query: `created_at:>='${start.toFormat(fmt)}' AND created_at:<'${end.toFormat(fmt)}'`,
    cursor: null,
    ordersGql: 'query Orders($query: String!, $cursor: String) { orders(first: 10, after: $cursor, query: $query, sortKey: CREATED_AT) { pageInfo { hasNextPage endCursor } nodes { id name createdAt cancelledAt test discountCodes currentTotalPriceSet { shopMoney { amount currencyCode } } totalShippingPriceSet { shopMoney { amount } } currentTotalDiscountsSet { shopMoney { amount } } lineItems(first: 25) { nodes { name sku currentQuantity discountedUnitPriceAfterAllDiscountsSet { shopMoney { amount } } product { id title } variant { id inventoryItem { unitCost { amount } } } } } } } }',
    variantsGql: 'query Variants($cursor: String) { productVariants(first: 100, after: $cursor) { pageInfo { hasNextPage endCursor } nodes { id title sku price product { id title status } inventoryItem { unitCost { amount } } } } }',
  },
}];

// Add this page of orders to the ones collected on earlier loop runs.
const cfg = $('Set Shopify Configurations').first().json;
const res = $input.first().json;
if (res.errors) throw new Error('Shopify GraphQL error: ' + JSON.stringify(res.errors).slice(0, 500));
const conn = res.data && res.data.orders;
if (!conn) throw new Error('Unexpected Shopify response: ' + JSON.stringify(res).slice(0, 300));

const win = $('Prepare Report Window').first().json;
const prev = $runIndex > 0 ? $('Process Orders Page').first(0, $runIndex - 1).json : { orders: [], pages: 0 };
const orders = prev.orders.concat(conn.nodes || []);
const pages = prev.pages + 1;
const more = Boolean(conn.pageInfo && conn.pageInfo.hasNextPage) && pages < (Number(cfg.maxPages) || 50);

return [{
  json: {
    ...win,
    orders,
    pages,
    cursor: conn.pageInfo ? conn.pageInfo.endCursor : null,
    hasNextPage: more,
    ordersTruncated: Boolean(conn.pageInfo && conn.pageInfo.hasNextPage) && !more,
  },
}];

// Add this page of product variants to the ones collected on earlier loop runs.
const cfg = $('Set Shopify Configurations').first().json;
const res = $input.first().json;
if (res.errors) throw new Error('Shopify GraphQL error: ' + JSON.stringify(res.errors).slice(0, 500));
const conn = res.data && res.data.productVariants;
if (!conn) throw new Error('Unexpected Shopify response: ' + JSON.stringify(res).slice(0, 300));

const prev = $runIndex > 0 ? $('Process Variants Page').first(0, $runIndex - 1).json : { variants: [], variantPages: 0 };
const variants = prev.variants.concat(conn.nodes || []);
const variantPages = prev.variantPages + 1;
const more = Boolean(conn.pageInfo && conn.pageInfo.hasNextPage) && variantPages < (Number(cfg.maxPages) || 50);

return [{
  json: {
    variants,
    variantPages,
    variantCursor: conn.pageInfo ? conn.pageInfo.endCursor : null,
    hasNextPage: more,
    variantsTruncated: Boolean(conn.pageInfo && conn.pageInfo.hasNextPage) && !more,
    variantsGql: $('Prepare Report Window').first().json.variantsGql,
  },
}];

// Calculate profit per order, per product and per discount code, and scan the catalog for pricing problems.
const cfg = $('Set Shopify Configurations').first().json;
// The loops accumulate pages, so the last run of each reader holds everything
const lastRun = (node) => {
  let last = null;
  for (let i = 0; i < 1000; i++) {
    let item;
    try { item = $(node).first(0, i); } catch (e) { break; }
    if (!item) break;
    last = item.json;
  }
  return last || {};
};
const ordersRun = lastRun('Process Orders Page');
const variantsRun = lastRun('Process Variants Page');

const n = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v));
const r2 = (v) => Math.round((Number(v) || 0) * 100) / 100;
const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : null);
const feePct = (n(cfg.paymentFeePercent) || 0) / 100;
const feeFixed = n(cfg.paymentFeeFixed) || 0;
const shipCost = n(cfg.shippingCostPerOrder) || 0;
const target = n(cfg.targetMarginPercent) || 30;
const lossThreshold = n(cfg.lossThreshold) || 0;

// ---------- orders
const orders = (ordersRun.orders || []).filter((o) => o && !o.test && !o.cancelledAt);
let currency = '';
const products = {};
const codes = {};
const missingCost = {};
const rows = [];

for (const o of orders) {
  currency = currency || (o.currentTotalPriceSet && o.currentTotalPriceSet.shopMoney.currencyCode) || '';
  const total = n(o.currentTotalPriceSet && o.currentTotalPriceSet.shopMoney.amount) || 0;
  const shipping = n(o.totalShippingPriceSet && o.totalShippingPriceSet.shopMoney.amount) || 0;
  const discount = n(o.currentTotalDiscountsSet && o.currentTotalDiscountsSet.shopMoney.amount) || 0;
  let itemsRevenue = 0;
  let cogs = 0;
  let costKnown = true;

  for (const li of (o.lineItems && o.lineItems.nodes) || []) {
    const qty = n(li.currentQuantity) || 0;
    if (!qty) continue;
    const unit = n(li.discountedUnitPriceAfterAllDiscountsSet && li.discountedUnitPriceAfterAllDiscountsSet.shopMoney.amount) || 0;
    const cost = n(li.variant && li.variant.inventoryItem && li.variant.inventoryItem.unitCost && li.variant.inventoryItem.unitCost.amount);
    const revenue = unit * qty;
    itemsRevenue += revenue;
    const key = (li.product && li.product.id) || li.name;
    const p = (products[key] = products[key] || { title: (li.product && li.product.title) || li.name, units: 0, revenue: 0, cogs: 0, costKnown: true });
    p.units += qty;
    p.revenue += revenue;
    if (cost === null || cost === 0) {
      costKnown = false;
      p.costKnown = false;
      missingCost[li.sku || li.name] = li.name;
    } else {
      cogs += cost * qty;
      p.cogs += cost * qty;
    }
  }

  const revenue = itemsRevenue + shipping;
  const fees = total > 0 ? total * feePct + feeFixed : 0;
  const profit = revenue - cogs - fees - shipCost;
  rows.push({ name: o.name, revenue, cogs, fees, profit, costKnown, codes: o.discountCodes || [], discount });

  for (const code of o.discountCodes || []) {
    const c = (codes[code] = codes[code] || { code, orders: 0, revenue: 0, discount: 0, profit: 0, unknown: 0 });
    c.orders += 1;
    c.revenue += revenue;
    c.discount += discount;
    c.profit += profit;
    if (!costKnown) c.unknown += 1;
  }
}

const sum = (k) => rows.reduce((a, r) => a + r[k], 0);
const revenue = sum('revenue');
const cogs = sum('cogs');
const fees = sum('fees');
const shippingCosts = rows.length * shipCost;
const grossProfit = revenue - cogs - fees - shippingCosts;

// ---------- optional ad spend (only when the Meta node is enabled and returned data)
let adSpend = null;
try {
  const meta = $('Fetch Meta Ad Spend').first().json;
  if (meta && Array.isArray(meta.data)) adSpend = meta.data.reduce((a, d) => a + (n(d.spend) || 0), 0);
} catch (e) { adSpend = null; }
const netProfit = adSpend === null ? null : grossProfit - adSpend;

const lossOrders = rows.filter((r) => r.costKnown && r.profit < lossThreshold).sort((a, b) => a.profit - b.profit);
const productList = Object.values(products).map((p) => ({ ...p, profit: p.revenue - p.cogs, marginPct: p.costKnown ? pct(p.revenue - p.cogs, p.revenue) : null }));

// ---------- catalog scan (active products only)
const catalog = (variantsRun.variants || []).filter((v) => v && v.product && v.product.status === 'ACTIVE');
const belowCost = [];
const lowMargin = [];
const noCost = [];
for (const v of catalog) {
  const price = n(v.price) || 0;
  const cost = n(v.inventoryItem && v.inventoryItem.unitCost && v.inventoryItem.unitCost.amount);
  const label = `${v.product.title}${v.title && v.title !== 'Default Title' ? ' / ' + v.title : ''}`;
  if (cost === null || cost === 0) { noCost.push(label); continue; }
  if (price <= 0) continue;
  const margin = pct(price * (1 - feePct) - feeFixed - cost, price);
  if (price <= cost) belowCost.push({ label, sku: v.sku, price, cost, margin });
  else if (margin < target) lowMargin.push({ label, sku: v.sku, price, cost, margin });
}
belowCost.sort((a, b) => a.margin - b.margin);
lowMargin.sort((a, b) => a.margin - b.margin);

return [{
  json: {
    date: ordersRun.label,
    currency,
    orders: rows.length,
    revenue: r2(revenue),
    cogs: r2(cogs),
    fees: r2(fees),
    shippingCosts: r2(shippingCosts),
    grossProfit: r2(grossProfit),
    grossMarginPct: pct(grossProfit, revenue),
    adSpend: adSpend === null ? null : r2(adSpend),
    netProfit: netProfit === null ? null : r2(netProfit),
    netMarginPct: netProfit === null ? null : pct(netProfit, revenue),
    aov: rows.length ? r2(revenue / rows.length) : 0,
    ordersMissingCosts: rows.filter((r) => !r.costKnown).length,
    lossOrderCount: lossOrders.length,
    lossOrders: lossOrders.slice(0, 10).map((r) => ({ order: r.name, revenue: r2(r.revenue), profit: r2(r.profit), codes: r.codes })),
    losingCodes: Object.values(codes).filter((c) => c.profit < 0).sort((a, b) => a.profit - b.profit).slice(0, 5)
      .map((c) => ({ code: c.code, orders: c.orders, discount: r2(c.discount), profit: r2(c.profit), ordersWithMissingCosts: c.unknown })),
    topProducts: productList.filter((p) => p.costKnown).sort((a, b) => b.profit - a.profit).slice(0, 3)
      .map((p) => ({ product: p.title, units: p.units, profit: r2(p.profit), marginPct: p.marginPct })),
    lowMarginSellers: productList.filter((p) => p.costKnown && p.marginPct !== null && p.marginPct < target).sort((a, b) => a.marginPct - b.marginPct).slice(0, 5)
      .map((p) => ({ product: p.title, units: p.units, revenue: r2(p.revenue), marginPct: p.marginPct })),
    missingCostItems: Object.values(missingCost).slice(0, 10),
    missingCostItemCount: Object.keys(missingCost).length,
    catalogChecked: catalog.length,
    belowCostCount: belowCost.length,
    belowCost: belowCost.slice(0, 10),
    lowMarginCount: lowMargin.length,
    lowMargin: lowMargin.slice(0, 5),
    noCostCount: noCost.length,
    targetMarginPct: target,
    dataTruncated: Boolean(ordersRun.ordersTruncated || variantsRun.variantsTruncated),
  },
}];

// Combine the calculated numbers with the AI commentary into one Slack message.
const s = $('Compute Profit and Analysis').first().json;
const ai = $input.first().json.output || {};
const m = (v) => (v === null || v === undefined ? 'n/a' : `${Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${s.currency}`);
const p = (v) => (v === null || v === undefined ? 'n/a' : `${v}%`);
const list = (arr, f) => arr.map((x) => `• ${f(x)}`).join('\n');
const icon = s.grossProfit < 0 ? ':red_circle:' : (s.grossMarginPct !== null && s.grossMarginPct < s.targetMarginPct) ? ':large_yellow_circle:' : ':large_green_circle:';

const parts = [
  `${icon} *Shopify profit report: ${s.date}*`,
  ai.headline ? `_${ai.headline}_` : '',
  `*Orders:* ${s.orders} | *Revenue:* ${m(s.revenue)} | *AOV:* ${m(s.aov)}`,
  `*COGS:* ${m(s.cogs)} | *Payment fees:* ${m(s.fees)} | *Shipping costs:* ${m(s.shippingCosts)}`,
  `*Gross profit:* ${m(s.grossProfit)} (${p(s.grossMarginPct)})` + (s.adSpend !== null ? ` | *Ad spend:* ${m(s.adSpend)} | *Net profit:* ${m(s.netProfit)} (${p(s.netMarginPct)})` : ''),
];
if (s.lossOrderCount) parts.push(`\n*:warning: ${s.lossOrderCount} loss-making order(s)*\n` + list(s.lossOrders.slice(0, 5), (o) => `${o.order}: profit ${m(o.profit)} on ${m(o.revenue)}${o.codes.length ? ' (code ' + o.codes.join(', ') + ')' : ''}`));
if (s.losingCodes.length) parts.push(`\n*Discount codes losing money*\n` + list(s.losingCodes, (c) => `${c.code}: ${c.orders} order(s), profit ${m(c.profit)}`));
if (s.lowMarginSellers.length) parts.push(`\n*Sold yesterday below ${s.targetMarginPct}% margin*\n` + list(s.lowMarginSellers, (x) => `${x.product}: ${p(x.marginPct)} on ${x.units} unit(s)`));
if (s.belowCostCount) parts.push(`\n*:rotating_light: ${s.belowCostCount} active variant(s) priced at or below cost*\n` + list(s.belowCost.slice(0, 5), (v) => `${v.label}${v.sku ? ' (' + v.sku + ')' : ''}: price ${m(v.price)}, cost ${m(v.cost)}`));
if (s.missingCostItemCount || s.noCostCount) parts.push(`\n*Missing product costs:* ${s.missingCostItemCount} item(s) sold yesterday and ${s.noCostCount} active variant(s) have no cost in Shopify, so their profit can't be measured.`);
if (ai.insights && ai.insights.length) parts.push(`\n*Insights*\n` + list(ai.insights, (x) => x));
if (ai.actions && ai.actions.length) parts.push(`\n*Suggested actions*\n` + list(ai.actions, (x) => x));
if (s.dataTruncated) parts.push('\n_Note: page limit reached, so some orders or variants were not included. Raise maxPages in Configuration._');

return [{ json: { text: parts.filter(Boolean).join('\n') } }];
